import { describe, expect, it } from 'vitest';
import { fromMintExportAssetPath, toMintExportAssetPath } from './mintExportAssets.js';
describe('toMintExportAssetPath', () => {
    it('maps an absolute url to a local asset path', () => {
        expect(toMintExportAssetPath('https://d3gk2c5xim1je2.cloudfront.net/fontawesome/v7.2.0/regular/house.svg')).toBe('/_mintlify/export-assets/d3gk2c5xim1je2.cloudfront.net/fontawesome/v7.2.0/regular/house.svg');
    });
    it('encodes the query string into the path with the given extension', () => {
        const assetPath = toMintExportAssetPath('https://fonts.googleapis.com/css2?family=Open+Sans:ital,wght@0,400;1,700&display=swap', 'css');
        expect(assetPath).toMatch(/^\/_mintlify\/export-assets\/fonts\.googleapis\.com\/css2\/_q\/[\w-]+\.css$/);
    });
    it('keeps the source extension for urls with a query', () => {
        expect(toMintExportAssetPath('https://cdn.example.com/style.css?v=1')).toMatch(/^\/_mintlify\/export-assets\/cdn\.example\.com\/style\.css\/_q\/[\w-]+\.css$/);
    });
    it('encodes ports without a colon so the path is valid on every file system', () => {
        expect(toMintExportAssetPath('https://fonts.example.com:8443/custom.woff2')).toBe('/_mintlify/export-assets/fonts.example.com~8443/custom.woff2');
    });
    it('keeps plain http assets distinct from https ones', () => {
        expect(toMintExportAssetPath('http://example.com/a.woff2')).toBe('/_mintlify/export-assets/_http/example.com/a.woff2');
    });
    it('leaves relative and non-http urls untouched', () => {
        expect(toMintExportAssetPath('/images/logo.svg')).toBe('/images/logo.svg');
        expect(toMintExportAssetPath('data:image/svg+xml,abc')).toBe('data:image/svg+xml,abc');
    });
});
describe('fromMintExportAssetPath', () => {
    it.each([
        'https://d3gk2c5xim1je2.cloudfront.net/flags/US.svg',
        'https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-400-normal.woff2',
        'https://fonts.googleapis.com/css2?family=Open+Sans:ital,wght@0,400;1,700&display=swap',
        'https://example.com/font.woff2?v=1&name=%C3%BC',
        'http://fonts.example.com/inter.woff2',
        'http://example.com/style.css?v=2',
        'https://example.com/font.WOFF2?v=1',
        'https://fonts.example.com:8443/custom.woff2',
        'http://localhost:8080/a.css?v=1',
    ])('round-trips %s', (url) => {
        expect(fromMintExportAssetPath(toMintExportAssetPath(url, 'css'))).toBe(url);
    });
    it('rejects paths outside the asset prefix or with traversal hosts', () => {
        expect(fromMintExportAssetPath('/images/logo.svg')).toBeUndefined();
        expect(fromMintExportAssetPath('/_mintlify/export-assets/../etc/passwd')).toBeUndefined();
    });
});
